#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100000

typedef struct {
    int to, next;
} Edge;

Edge edges[2 * MAXN];
int head[MAXN], edge_cnt;
int covered[MAXN];
int ans;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void dfs(int u, int parent) {
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == parent) continue;
        dfs(v, u);
        if (!covered[v] && !covered[u]) {
            covered[u] = 1;
            ans++;
        }
    }
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    memset(head, -1, sizeof(head));
    edge_cnt = 0;
    ans = 0;
    memset(covered, 0, sizeof(covered));

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        add_edge(u, v);
        add_edge(v, u);
    }

    dfs(0, -1);

    printf("%d\n", ans);
    return 0;
}

