int main(void) {
    int n, m;

    /* 
       Assumption from the statement:
       - n = number of historical sites
       - m = number of roads
       - each road is given by: site1 site2 distance
       - lanterns are needed every 100 meters along roads
       - distance between sites is at least 200 meters, so endpoints are not enough

       To illuminate/reach all sites through the roads, the minimum number of lanterns
       is simply the sum over all roads of floor(distance / 100).

       This matches the requirement of placing lanterns every 100 meters.
    */

    if (scanf("%d %d", &n, &m) != 2) return 0;

    long long answer = 0;
    for (int i = 0; i < m; i++) {
        int a, b;
        long long d;
        if (scanf("%d %d %lld", &a, &b, &d) != 3) return 0;
        answer += d / 100;
    }

    printf("%lld\n", answer);
    return 0;
}

