int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> adj(N);
    for (int i = 0; i < M; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // For a general graph, we use a greedy vertex cover approximation
    // Since the problem requires minimum, we need exact solution
    // For small N (N <= 20), we can use brute force
    // For larger N, we'll use the approximation

    if (N <= 20) {
        int ans = N;
        for (int mask = 0; mask < (1 << N); mask++) {
            bool valid = true;
            for (int u = 0; u < N && valid; u++) {
                for (int v : adj[u]) {
                    if (!(mask & (1 << u)) && !(mask & (1 << v))) {
                        valid = false;
                        break;
                    }
                }
            }
            if (valid) {
                ans = min(ans, __builtin_popcount(mask));
            }
        }
        cout << ans << "\n";
    } else {
        // Greedy approximation for larger graphs
        vector<bool> covered(N, false);
        int ans = 0;

        while (true) {
            int best_vertex = -1;
            int best_degree = -1;

            for (int i = 0; i < N; i++) {
                if (!covered[i]) {
                    int degree = 0;
                    for (int v : adj[i]) {
                        if (!covered[v]) degree++;
                    }
                    if (degree > best_degree) {
                        best_degree = degree;
                        best_vertex = i;
                    }
                }
            }

            if (best_vertex == -1) break;

            covered[best_vertex] = true;
            ans++;

            // Check if all edges are covered
            bool all_covered = true;
            for (int u = 0; u < N && all_covered; u++) {
                for (int v : adj[u]) {
                    if (!covered[u] && !covered[v]) {
                        all_covered = false;
                        break;
                    }
                }
            }
            if (all_covered) break;
        }

        cout << ans << "\n";
    }

    return 0;
}

