/*
Interpretation:
- Historical sites are vertices.
- Roads connect pairs of sites.
- A lantern placed on a road illuminates/reaches the two endpoint sites.
- We need the minimum number of lanterns so that every site is reached.
- Since sites are at least 200m apart and lanterns are placed every 100m,
  one lantern on a road can cover its two endpoint sites independently of road length details.
Thus the problem becomes: find the minimum number of edges such that every vertex
is incident to at least one chosen edge -> Minimum Edge Cover.

For an undirected graph with no isolated vertices:
    min edge cover = n - size(maximum matching)

If isolated vertices exist, they cannot be covered by any road; in that case we count
them as needing no road-lantern coverage only if the problem guarantees connectivity enough.
To stay safe, we use the general formula:
    min edge cover = isolated_vertices + (non_isolated_vertices - maximum_matching_on_non_isolated)
which is equivalent to n - maximum_matching when isolated vertices are included properly.

Input format is not explicitly stated, so we assume a common format:
n m
u1 v1
...
um vm

Vertices may be numbered either 0..n-1 or 1..n. We support both by detecting.
Because the graph is general, we use Edmonds' blossom algorithm for maximum matching.
*/

struct EdmondsBlossom {
    int n;
    vector<vector<int>> g;
    vector<int> match, p, base;
    vector<bool> used, blossom;
    queue<int> q;

    EdmondsBlossom(int n) : n(n), g(n), match(n, -1), p(n), base(n), used(n), blossom(n) {}

    void addEdge(int u, int v) {
        if (u == v) return;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    int lca(int a, int b) {
        vector<bool> usedLca(n, false);
        while (true) {
            a = base[a];
            usedLca[a] = true;
            if (match[a] == -1) break;
            a = p[match[a]];
        }
        while (true) {
            b = base[b];
            if (usedLca[b]) return b;
            if (match[b] == -1) break;
            b = p[match[b]];
        }
        return -1;
    }

    void markPath(int v, int b, int children) {
        while (base[v] != b) {
            blossom[base[v]] = blossom[base[match[v]]] = true;
            p[v] = children;
            children = match[v];
            v = p[match[v]];
        }
    }

    int findPath(int root) {
        fill(used.begin(), used.end(), false);
        fill(p.begin(), p.end(), -1);
        iota(base.begin(), base.end(), 0);
        while (!q.empty()) q.pop();

        q.push(root);
        used[root] = true;

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (int u : g[v]) {
                if (base[v] == base[u] || match[v] == u) continue;
                if (u == root || (match[u] != -1 && p[match[u]] != -1)) {
                    int curbase = lca(v, u);
                    fill(blossom.begin(), blossom.end(), false);
                    markPath(v, curbase, u);
                    markPath(u, curbase, v);
                    for (int i = 0; i < n; ++i) {
                        if (blossom[base[i]]) {
                            base[i] = curbase;
                            if (!used[i]) {
                                used[i] = true;
                                q.push(i);
                            }
                        }
                    }
                } else if (p[u] == -1) {
                    p[u] = v;
                    if (match[u] == -1) {
                        v = u;
                        while (v != -1) {
                            int pv = p[v];
                            int nv = (pv == -1 ? -1 : match[pv]);
                            match[v] = pv;
                            if (pv != -1) match[pv] = v;
                            v = nv;
                        }
                        return 1;
                    } else {
                        used[match[u]] = true;
                        q.push(match[u]);
                    }
                }
            }
        }
        return 0;
    }

    int maximumMatching() {
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if (match[i] == -1) ans += findPath(i);
        }
        return ans;
    }
};

