import java.util.*;

public class Main {
    static int n, m;
    static List<int[]> edges = new ArrayList<>();
    static int[][] dist;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        dist = new int[n][n];
        for (int[] row : dist) Arrays.fill(row, -1);

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            int l = sc.nextInt();
            edges.add(new int[]{u, v, l});
            dist[u][v] = l;
            dist[v][u] = l;
        }

        // Maximum matching using DP over subsets (N <= 20)
        int[] dp = new int[1 << n];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        int maxMatch = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == -1) continue;
            int first = -1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    first = i;
                    break;
                }
            }
            if (first == -1) {
                maxMatch = Math.max(maxMatch, dp[mask]);
                continue;
            }
            for (int j = first + 1; j < n; j++) {
                if ((mask & (1 << j)) == 0 && dist[first][j] != -1) {
                    int newMask = mask | (1 << first) | (1 << j);
                    dp[newMask] = Math.max(dp[newMask], dp[mask] + 1);
                }
            }
            // Also skip first (leave unmatched)
            int skipMask = mask | (1 << first);
            dp[skipMask] = Math.max(dp[skipMask], dp[mask]);
        }

        int coverSize = n - maxMatch;

        // We need to select exactly coverSize edges covering all vertices minimally.
        // We'll do another DP to find min cost edge cover.
        int[] costDP = new int[1 << n];
        Arrays.fill(costDP, Integer.MAX_VALUE / 2);
        costDP[0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            if (costDP[mask] >= Integer.MAX_VALUE / 2) continue;
            int first = -1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    first = i;
                    break;
                }
            }
            if (first == -1) continue;
            // Try to cover first with some edge
            for (int[] e : edges) {
                int u = e[0], v = e[1], L = e[2];
                int newMask = mask;
                int addCost = 0;
                if (u == first && (mask & (1 << v)) == 0) {
                    newMask |= (1 << u) | (1 << v);
                    addCost = 2 + Math.max(0, (L - 200) / 100);
                } else if (v == first && (mask & (1 << u)) == 0) {
                    newMask |= (1 << u) | (1 << v);
                    addCost = 2 + Math.max(0, (L - 200) / 100);
                }
                if (newMask != mask) {
                    costDP[newMask] = Math.min(costDP[newMask], costDP[mask] + addCost);
                }
            }
            // Also leave first unmatched? Not allowed in cover
        }

        System.out.println(costDP[(1 << n) - 1]);
    }
}

import java.util.*;

public class Main {
    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static boolean union(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) { int t = px; px = py; py = t; }
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            int m = sc.nextInt();

            int[][] edges = new int[m][3];
            for (int i = 0; i < m; i++) {
                edges[i][0] = sc.nextInt(); // u
                edges[i][1] = sc.nextInt(); // v
                edges[i][2] = sc.nextInt(); // distance
            }

            Arrays.sort(edges, (a, b) -> a[2] - b[2]);

            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 0; i <= n; i++) { parent[i] = i; rank[i] = 0; }

            int totalLanterns = 0;
            int edgesUsed = 0;

            for (int[] edge : edges) {
                if (union(edge[0], edge[1])) {
                    totalLanterns += edge[2] / 100 - 1;
                    edgesUsed++;
                    if (edgesUsed == n - 1) break;
                }
            }

            System.out.println(totalLanterns);
        }
    }
}

import java.io.*;
